    $$('#leftContent [data-effect-delete]').forEach(b=>b.addEventListener('click',()=>{const c=selectedClip();c.effects.splice(Number(b.dataset.effectDelete),1);snapshot('Delete effect');renderAll()}));
    $$('#leftContent [data-effect-param]').forEach(i=>{i.addEventListener('input',()=>{const c=selectedClip();c.effects[Number(i.dataset.effectParam)].amount=Number(i.value);drawPreview()});i.addEventListener('change',()=>snapshot('Changed effect amount'))});
    $('#addText')?.addEventListener('click',addText);$$('[data-shape]').forEach(b=>b.addEventListener('click',()=>addShape(b.dataset.shape)));$$('[data-text-anim]').forEach(b=>b.addEventListener('click',()=>{const c=selectedClip();if(!c?.text)return toast('Select a text clip.');c.text.animation=b.dataset.textAnim;snapshot(`Text animation ${b.dataset.textAnim}`);renderAll()}));
    $$('[data-audio-tool]').forEach(b=>b.addEventListener('click',()=>audioAction(b.dataset.audioTool)));
    $('#projectName')?.addEventListener('change',()=>{state.project.name=$('#projectName').value;snapshot('Project name');renderProjectPanel()});
    $('#aspectSelect')?.addEventListener('change',e=>applyAspect(e.target.value));$('#projW')?.addEventListener('change',()=>{state.project.width=clamp(Number($('#projW').value),64,7680);snapshot('Project width');updatePreviewSize()});$('#projH')?.addEventListener('change',()=>{state.project.height=clamp(Number($('#projH').value),64,7680);snapshot('Project height');updatePreviewSize()});$('#projFps')?.addEventListener('change',()=>{state.project.fps=Number($('#projFps').value);snapshot('Project fps');renderTimeline()});$('#perf')?.addEventListener('change',e=>{state.project.performance=e.target.value;drawPreview()});$('#openProjectSettings')?.addEventListener('click',showProjectSettings);$('#relinkMedia')?.addEventListener('click',tryRelink);$('#showFeatures')?.addEventListener('click',showFeatures);$('#showHistory')?.addEventListener('click',showHistory);
    $('#savePreset')?.addEventListener('click',savePreset);
